-- Synthetic contract used only by tests; no production data or catalog exports.
CREATE TABLE IF NOT EXISTS public.marketing_daily_spend(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(),date date NOT NULL,meta_campaign_id text,meta_campaign_name text,
 meta_adset_id text,meta_adset_name text,meta_ad_id text,meta_ad_name text,spend_bdt numeric,spend_usd numeric,
 impressions integer,reach integer,clicks integer,link_clicks integer,conversations integer,frequency numeric,ctr numeric,cpc numeric,cpm numeric,
 source_payload jsonb,updated_at timestamptz DEFAULT now(),UNIQUE(date,meta_campaign_id,meta_adset_id,meta_ad_id));

CREATE OR REPLACE FUNCTION public.call_kpi_patient_type_label(p_type text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT CASE WHEN lower(coalesce(p_type,''))='new' THEN 'New' WHEN lower(coalesce(p_type,''))='old' THEN 'Old' ELSE 'Unknown' END $$;
CREATE TABLE IF NOT EXISTS public.patients(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,hn text,phone_e164 text);
CREATE TABLE IF NOT EXISTS public.invoices(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id integer,invoice_date date,invoice_type text,invoice_status text DEFAULT 'issued',reconciliation_status text DEFAULT 'matched',net_bill numeric DEFAULT 0);
CREATE TABLE IF NOT EXISTS public.invoice_line_items(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,invoice_id bigint,category_name text,item_type text,particulars text);
CREATE TABLE IF NOT EXISTS public.call_center_logs(id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id integer,matched_patient_id integer,patient_id_raw text,mobile_e164 text,log_date date,lead_source text,call_source text,call_category text,matched_confidence numeric,ad_campaign text);
CREATE TABLE IF NOT EXISTS public.crm_leads(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id integer,source text,source_system text DEFAULT 'app',external_lead_id text,created_at timestamptz DEFAULT now(),call_direction text,campaign_name text,meta_ad_id_conflict boolean,validated_meta_ad_id text);
CREATE TABLE IF NOT EXISTS public.crm_appointments(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,patient_id integer);
CREATE TABLE IF NOT EXISTS public.excluded_billing_invoices(invoice_id bigint PRIMARY KEY);
CREATE TABLE IF NOT EXISTS public.backlog_patient_invoices(invoice_id bigint PRIMARY KEY);
CREATE TABLE IF NOT EXISTS public.marketing_campaign_map(meta_campaign_id text,campaign_bucket text,exclude_from_benchmarks boolean,internal_type_code text);
CREATE TABLE IF NOT EXISTS public.lead_attribution(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),patient_id integer,lead_id bigint,call_center_log_id integer,source_category text,first_touch_date date,attribution_confidence numeric,attribution_level text,meta_campaign_name text,meta_campaign_id text,meta_ad_id text);
CREATE TABLE IF NOT EXISTS public.referral_patient_report(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,hospital_number text,reg_date timestamptz,mpo_name text);
CREATE TABLE IF NOT EXISTS public.messenger_contacts(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,psid text,page_id text,converted_crm_lead_id bigint);
CREATE TABLE IF NOT EXISTS public.messenger_attribution_touches(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,psid text,page_id text,touched_at timestamptz,campaign_name text,campaign_id text,ad_id text);
CREATE TABLE IF NOT EXISTS public.meta_message_phone_candidates(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,psid text,page_id text,reconciliation_status text);
CREATE TABLE IF NOT EXISTS public.meta_call_center_reconciliation(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,meta_candidate_id bigint,selected_crm_lead_id bigint,review_status text,reviewed_at timestamptz);
CREATE TABLE IF NOT EXISTS public.patient_marketing_attribution(patient_id integer PRIMARY KEY,first_touch_source text,first_touch_date date,first_touch_evidence_table text,first_touch_evidence_id text,latest_touch_source text,latest_touch_date date,conversion_source text,conversion_date date,validated_source text,source_priority integer DEFAULT 0,campaign_id text,campaign_name text,confidence numeric,is_authenticated boolean DEFAULT false,authentication_method text,evidence_count integer DEFAULT 0,rebuilt_at timestamptz DEFAULT now(),created_at timestamptz DEFAULT now(),updated_at timestamptz DEFAULT now());

CREATE TABLE IF NOT EXISTS public.meta_ad_spend_daily(id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,spend_date date,ad_account_id text,currency text,ad_id text,ad_name text,campaign_id text,adset_id text,amount_spent numeric,synced_at timestamptz DEFAULT now(),raw_payload jsonb,UNIQUE(ad_account_id,spend_date,ad_id));
